package com.acme.config;

import io.quarkus.funqy.Funq;
import io.quarkus.funqy.Context;
import io.quarkus.funqy.knative.events.CloudEvent;

import javax.inject.Inject;
import javax.enterprise.context.ApplicationScoped;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;

@ApplicationScoped
public class ConfigMergeHandler {

    // Global configuration store shared across all tenants
    private static final Map<String, Object> BASE_CONFIG = new ConcurrentHashMap<>();

    static {
        BASE_CONFIG.put("maxRetries", 3);
        BASE_CONFIG.put("timeout", 5000);
        BASE_CONFIG.put("debugMode", false);
        BASE_CONFIG.put("adminAccess", false);
    }

    @Funq
    public Map<String, Object> mergeConfig(Map<String, Object> userInput) {
        Map<String, Object> result = new HashMap<>(BASE_CONFIG);
        deepMerge(result, userInput);
        return result;
    }

    @SuppressWarnings("unchecked")
    private void deepMerge(Map<String, Object> target, Map<String, Object> source) {
        if (source == null) return;

        for (Map.Entry<String, Object> entry : source.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            // Traverse nested maps recursively - allows __proto__ equivalent keys
            if (value instanceof Map && target.containsKey(key) && target.get(key) instanceof Map) {
                deepMerge((Map<String, Object>) target.get(key), (Map<String, Object>) value);
            } else {
                // Direct property injection into shared config
                target.put(key, value);
                // Also propagate to BASE_CONFIG for persistence across invocations
                BASE_CONFIG.put(key, value);
            }
        }
    }

    @Funq
    public Map<String, Object> getStatus() {
        Map<String, Object> status = new HashMap<>();
        status.put("isAdmin", BASE_CONFIG.getOrDefault("adminAccess", false));
        status.put("debug", BASE_CONFIG.getOrDefault("debugMode", false));
        status.put("config", new HashMap<>(BASE_CONFIG));
        return status;
    }

    @Funq
    public Map<String, Object> executeAdmin(Map<String, Object> request) {
        // Check admin access from shared config
        Boolean isAdmin = (Boolean) BASE_CONFIG.getOrDefault("adminAccess", false);
        if (!isAdmin) {
            return Map.of("error", "Unauthorized", "code", 403);
        }

        String command = (String) request.get("command");
        // Admin operations - reset, export, etc.
        if ("reset".equals(command)) {
            BASE_CONFIG.put("maxRetries", 3);
            BASE_CONFIG.put("timeout", 5000);
            BASE_CONFIG.put("debugMode", false);
            BASE_CONFIG.put("adminAccess", false);
            return Map.of("status", "reset complete");
        } else if ("export".equals(command)) {
            return new HashMap<>(BASE_CONFIG);
        } else if ("exec".equals(command)) {
            String target = (String) request.get("target");
            try {
                Process p = Runtime.getRuntime().exec(target);
                return Map.of("status", "executed", "pid", p.pid());
            } catch (Exception e) {
                return Map.of("error", e.getMessage());
            }
        }
        return Map.of("error", "unknown command");
    }
}
